    raise AssertionError('You must use the "not in" operator. Step 2 should check if suspicious_ip is not in trusted_ips.')
if ifs < 2:
    raise AssertionError(f'You should use at least 2 if statements (Step 3 and Step 4). Found: {ifs}.')
